import express from 'express';
import { createClient } from 'redis';
import crypto from 'crypto';
import { execFile } from 'child_process';
import path from 'path';

const app = express();
app.use(express.json());

const redis = createClient({ url: process.env.REDIS_URL });
await redis.connect();

// Template rendering engine for PDF reports
const ALLOWED_TEMPLATES = ['invoice', 'receipt', 'statement', 'summary'];

function sanitizeFilename(name) {
  // Remove path traversal attempts
  return name.replace(/\.\.\//g, '').replace(/\//g, '');
}

function validateJobId(id) {
  return /^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$/.test(id);
}

// Queue a PDF generation job
app.post('/api/v1/reports/generate', async (req, res) => {
  const { template, customer_id, options } = req.body;

  if (!template || !ALLOWED_TEMPLATES.includes(template)) {
    return res.status(400).json({ error: 'Invalid template' });
  }

  if (!customer_id || typeof customer_id !== 'string') {
    return res.status(400).json({ error: 'Invalid customer_id' });
  }

  const jobId = crypto.randomUUID();
  const jobData = {
    id: jobId,
    template: sanitizeFilename(template),
    customer_id,
    options: options || {},
    status: 'queued',
    created_at: Date.now()
  };

  await redis.hSet(`job:${jobId}`, jobData);
  await redis.lPush('pdf_queue', jobId);

  res.json({ job_id: jobId, status: 'queued' });
});

// Worker: process PDF generation jobs from queue
async function processJob() {
  const jobId = await redis.rPop('pdf_queue');
  if (!jobId || !validateJobId(jobId)) return;

  const job = await redis.hGetAll(`job:${jobId}`);
  if (!job || !job.template) return;

  await redis.hSet(`job:${jobId}`, 'status', 'processing');

  // Build wkhtmltopdf command with customer options
  const templatePath = path.join('/app/templates', `${job.template}.html`);
  const outputPath = path.join('/app/output', `${jobId}.pdf`);

  // Options from user request are passed as wkhtmltopdf flags
  const args = ['--quiet', '--disable-javascript'];

  if (job.options) {
    const opts = typeof job.options === 'string' ? JSON.parse(job.options) : job.options;

    // Allow custom header/footer text
    if (opts.header_text) {
      args.push('--header-center', opts.header_text);
    }
    if (opts.footer_text) {
      args.push('--footer-center', opts.footer_text);
    }
    // Allow custom page size
    if (opts.page_size && /^[A-Za-z0-9]+$/.test(opts.page_size)) {
      args.push('--page-size', opts.page_size);
    }
    // Allow custom margins
    if (opts.margin_top) {
      args.push('--margin-top', String(opts.margin_top));
    }
    // Allow additional stylesheet URL for branding
    if (opts.stylesheet_url) {
      args.push('--user-style-sheet', opts.stylesheet_url);
    }
  }

  args.push(templatePath, outputPath);

  execFile('/usr/local/bin/wkhtmltopdf', args, { timeout: 30000 }, async (err) => {
    if (err) {
      await redis.hSet(`job:${jobId}`, 'status', 'failed');
      return;
    }
    await redis.hSet(`job:${jobId}`, 'status', 'complete');
    await redis.hSet(`job:${jobId}`, 'output_path', outputPath);
  });
}

// Poll for jobs
setInterval(processJob, 1000);

// Status endpoint
app.get('/api/v1/reports/:jobId/status', async (req, res) => {
  const { jobId } = req.params;
  if (!validateJobId(jobId)) return res.status(400).json({ error: 'Invalid job ID' });

  const job = await redis.hGetAll(`job:${jobId}`);
  if (!job || !job.id) return res.status(404).json({ error: 'Job not found' });

  res.json({ id: job.id, status: job.status });
});

app.listen(3000, () => console.log('Report service running on :3000'));
